Do 'LoadGridState' Do Case Case &DDOName.ToUpper() = !'DDO_PREFNOME' Do 'LoadprefNomeOptions' Case &DDOName.ToUpper() = !'DDO_PREFCNPJ' Do 'LoadprefCNPJOptions' Case &DDOName.ToUpper() = !'DDO_PREFMUNICIPIO' Do 'LoadPrefMunicipioOptions' Case &DDOName.ToUpper() = !'DDO_PREFESTADO' Do 'LoadprefEstadoOptions' Case &DDOName.ToUpper() = !'DDO_PREFTELEFONE' Do 'LoadprefTelefoneOptions' Case &DDOName.ToUpper() = !'DDO_PREFCONTATO' Do 'LoadprefContatoOptions' EndCase
