Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsprefeiturasWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsprefeiturasWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsprefeiturasWWGridState")) Endif
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFPREFCODIGO" &TFprefCodigo.FromString(&GridStateFilterValue.Value) &TFprefCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFPREFNOME" &TFprefNome.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFNOME_SEL" &TFprefNome_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFCNPJ" &TFprefCNPJ.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFCNPJ_SEL" &TFprefCNPJ_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFMUNICIPIO" &TFPrefMunicipio.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFMUNICIPIO_SEL" &TFPrefMunicipio_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFESTADO" &TFprefEstado.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFESTADO_SEL" &TFprefEstado_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFTELEFONE" &TFprefTelefone.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFTELEFONE_SEL" &TFprefTelefone_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFCONTATO" &TFprefContato.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFCONTATO_SEL" &TFprefContato_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFSTATUS_SEL" &TFprefStatus_SelsJson = &GridStateFilterValue.Value &TFprefStatus_Sels.FromJson(&TFprefStatus_SelsJson) EndCase EndFor If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'PREFMUNICIPIO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &PrefMunicipio1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'PREFNOME' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &prefNome1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'PREFCNPJ' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &prefCNPJ1.FromString(&GridStateDynamicFilter.Value) EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'PREFMUNICIPIO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &PrefMunicipio2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'PREFNOME' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &prefNome2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'PREFCNPJ' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &prefCNPJ2.FromString(&GridStateDynamicFilter.Value) EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'PREFMUNICIPIO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &PrefMunicipio3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'PREFNOME' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &prefNome3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'PREFCNPJ' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &prefCNPJ3.FromString(&GridStateDynamicFilter.Value) EndCase EndIf EndIf EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadprefNomeOptions'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&TFprefNome = &SearchTxt &TFprefNome_Sel.SetEmpty() For Each trnsprefeituras Order prefNome using trnsprefeiturasWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &PrefMunicipio1, &prefNome1, &prefCNPJ1, &DynamicFiltersEnabled2 , &DynamicFiltersSelector2, &DynamicFiltersOperator2, &PrefMunicipio2, &prefNome2, &prefCNPJ2, &DynamicFiltersEnabled3 , &DynamicFiltersSelector3, &DynamicFiltersOperator3, &PrefMunicipio3, &prefNome3, &prefCNPJ3, &TFprefCodigo , &TFprefCodigo_To, &TFprefNome, &TFprefNome_Sel, &TFprefCNPJ, &TFprefCNPJ_Sel, &TFPrefMunicipio , &TFPrefMunicipio_Sel, &TFprefEstado, &TFprefEstado_Sel, &TFprefTelefone, &TFprefTelefone_Sel, &TFprefContato , &TFprefContato_Sel, &TFprefStatus_Sels)
&count = 0 For Each trnsprefeituras Order prefNome &count += 1 EndFor If not prefNome.IsEmpty() &Option = prefNome
&Options.Add(&Option) &OptionIndexes.Add(trim(&count.ToFormattedString())) EndIf If &Options.Count = 50 Exit EndIf EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
